diff --git a/ClockViewController.swift b/ClockViewController.swift
index 3d738e1..d0eb5eb 100644
--- a/ClockViewController.swift
+++ b/ClockViewController.swift
@@ -12,8 +12,19 @@ final class ClockViewController: UIViewController {

     override func viewDidAppear(_ animated: Bool) {
         super.viewDidAppear(animated)
-        timer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { _ in
-            self.label.text = Date().description
+        guard timer == nil else { return }
+        timer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] _ in
+            self?.label.text = Date().description
         }
     }
+
+    override func viewDidDisappear(_ animated: Bool) {
+        super.viewDidDisappear(animated)
+        timer?.invalidate()
+        timer = nil
+    }
+
+    deinit {
+        timer?.invalidate()
+    }
 }

